let revealObserver;
function initReveals(){if(!('IntersectionObserver'in window)||window.matchMedia('(prefers-reduced-motion:reduce)').matches)return;revealObserver ||=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');revealObserver.unobserve(entry.target);}}),{threshold:.12});document.querySelectorAll('.reveal:not(.is-visible)').forEach(el=>revealObserver.observe(el));}

const stored=(k)=>{try{return JSON.parse(localStorage.getItem('ml-'+k))}catch{return null}};
const save=(k,v)=>{try{localStorage.setItem('ml-'+k,JSON.stringify(v))}catch{}};
const utcDate=s=>{if(!s||!/^\d{4}-\d{2}-\d{2}$/.test(s))return null;let d=new Date(s+'T12:00:00');return Number.isFinite(d.getTime())?d:null};const dayDiff=(a,b)=>Math.round((a.getTime()-b.getTime())/86400000);const addDays=(date,n)=>{let d=new Date(date);d.setDate(d.getDate()+n);return d};const niceDate=d=>d.toLocaleDateString('en-GB',{month:'short',day:'numeric',year:'numeric'});const put=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v};
function initPregnancy(){const form=document.getElementById('pregnancyForm');if(!form)return;const old=stored('preg');if(old){document.getElementById('lmp').value=old.lmp||'';document.getElementById('due').value=old.due||'';update(old)}form.addEventListener('submit',e=>{e.preventDefault();const v={lmp:document.getElementById('lmp').value,due:document.getElementById('due').value};save('preg',v);update(v)});function update(v){let l=utcDate(v.lmp);const due=utcDate(v.due);if(!l&&due)l=addDays(due,-280);if(!l){put('pregTitle','Please enter one of the dates.');return}const today=new Date();const days=dayDiff(today,l);if(days<0||days>325){put('pregTitle','Please check your dates.');put('pregDescription','The calculated date is outside a typical pregnancy timeline.');put('pregWeek','—');return}const week=Math.floor(days/7),rem=days%7;put('pregWeek',`Week ${week}`);put('pregTitle',`${week} weeks + ${rem} days`);put('pregDescription',`Use your maternity team’s confirmed dates when planning appointments or care.`);put('pregDay',`${rem}/7`);put('pregTrim',week<14?'1st':week<28?'2nd':'3rd');put('pregDue',niceDate(addDays(l,280)))}}
function initPeriod(){let form=document.getElementById('periodForm');if(!form)return;const old=stored('cycle');if(old){document.getElementById('lastPeriod').value=old.lastPeriod||'';document.getElementById('cycleLength').value=old.cycleLength||28;document.getElementById('flowLength').value=old.flowLength||5;update(old)}form.addEventListener('submit',e=>{e.preventDefault();const v={lastPeriod:document.getElementById('lastPeriod').value,cycleLength:+document.getElementById('cycleLength').value,flowLength:+document.getElementById('flowLength').value};save('cycle',v);update(v)});function update(v){const last=utcDate(v.lastPeriod);if(!last)return;const cycle=+v.cycleLength||28;const elapsed=dayDiff(new Date(),last);if(elapsed<0){put('cycleTitle','Check your last period date.');return}const periodsPassed=Math.max(1,Math.floor(elapsed/cycle)+1);const next=addDays(last,cycle*periodsPassed);let remaining=dayDiff(next,new Date());put('cycleCount',remaining+' days');put('cycleTitle','Until your next estimated period');put('cycleDescription','Your cycle may be shorter or longer than predicted, especially when your body is changing.');put('cycleNext',niceDate(next).replace(/, \d{4}/,''));put('cycleAvg',cycle+' days');put('cycleFlow',(+v.flowLength||5)+' days')}}
function initBaby(){let form=document.getElementById('babyForm');if(!form)return;const old=stored('baby');if(old?.dob){document.getElementById('babyDob').value=old.dob;update(old.dob)}form.addEventListener('submit',e=>{e.preventDefault();const v=document.getElementById('babyDob').value;save('baby',{dob:v});update(v)});function update(value){const birth=utcDate(value);if(!birth)return;const days=dayDiff(new Date(),birth);if(days<0||days>365*7){put('babyTitle','Please check the birth date.');return}let months=Math.max(0,Math.floor(days/30.4375));put('babyAge',months+' mo.');put('babyTitle',days<31?'Your newborn’s age':'Your baby’s approximate age');put('babyDesc',`Approximately ${months} completed months (${days} days) since birth. Age estimates do not assess development.`);put('babyMonths',months);put('babyDays',days)}const checks=[...document.querySelectorAll('.milestone-check')];const prior=stored('milestones')||[];checks.forEach((x,i)=>{x.checked=!!prior[i];x.addEventListener('change',()=>{save('milestones',checks.map(c=>c.checked));count()})});function count(){const n=checks.filter(c=>c.checked).length;put('babyTicks',`${n}/${checks.length}`);document.getElementById('milestoneProgress').style.width=(100*n/checks.length)+'%'}count()}
initPregnancy();initPeriod();initBaby();initLearn();if(['growth','pregnancy-growth','baby-growth'].includes(page))window.MamasGrowth.init();initQuickTrackers();initGuideFilters();initHeroTabs();initReveals();

function initAmbientMotion() {
  const button = document.getElementById('motionToggle');
  const preference = window.matchMedia('(prefers-reduced-motion: reduce)');
  let manuallyPaused = stored('motion') === true;

  function applyPreference() {
    const paused = preference.matches || manuallyPaused;
    document.documentElement.dataset.backgroundPaused = String(paused);
    button.hidden = preference.matches;
    button.setAttribute('aria-pressed', String(!paused));
    button.title = paused ? 'Play animated background' : 'Pause animated background';
    document.getElementById('motionLabel').textContent = paused ? 'Play background' : 'Pause background';
    document.getElementById('motionIcon').innerHTML = icon(paused ? 'play' : 'pause');
  }

  button.addEventListener('click', () => {
    manuallyPaused = !manuallyPaused;
    save('motion', manuallyPaused);
    applyPreference();
  });
  preference.addEventListener('change', applyPreference);
  function applyVisibility() {
    document.documentElement.dataset.backgroundSuspended = String(document.hidden);
  }
  document.addEventListener('visibilitychange', applyVisibility);
  applyPreference();
  applyVisibility();
}

initAmbientMotion();

if (window.MamasMotion) window.MamasMotion.mount(document.getElementById("ambientCanvas"));
